const I18N = {};
for (const row of I18N_ROWS) Object.keys(LANGS).forEach((l, i) => { if (i) (I18N[l] ??= {})[row[0]] = row[i]; });

let LANG = 'de';
const locale = () => LOCALES[LANG];
// t('Prüfe Fans: {done} von {total}', { done: 3, total: 9 })
function t(s, vars) {
  let out = (LANG !== 'de' && I18N[LANG]?.[s]) || s;
  if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  return out;
}
// Feste Texte der Seite übersetzen. Das deutsche Original jedes Textknotens/Attributs wird gemerkt;
// hat ein render…() den Text inzwischen selbst gesetzt, gilt der neue Text als Original.
const i18nOrig = new WeakMap();
function swap(obj, k, cur) {
  const m = (i18nOrig.get(obj) || i18nOrig.set(obj, {}).get(obj));
  if (m[k]?.set !== cur) m[k] = { de: cur };
  const key = m[k].de.trim();
  if (!I18N.en[key]) return null;
  return (m[k].set = m[k].de.replace(key, t(key)));
}
// Listen, Titel und Meldungen setzen ihre Texte selbst über t() – Bandnamen o. Ä. dort nie „übersetzen“
const I18N_SKIP = 'script, style, #log, #setupHint, datalist, .list, #nowTitle, #nowArtist, #pendingTitle, #plTitle, #status, #toast, .tagbar, #hiddenInfo, #hiddenCount, #btnHiddenAll, #historyInfo, #soulProg, .hhinfo, #pplPop, #genreInc, #genreExc, #genreSugg, #genreLoad';
function applyI18n(root = document.body) {
  document.documentElement.lang = LANG;
  const walk = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let n; (n = walk.nextNode());) {
    if (!n.nodeValue.trim() || n.parentElement?.closest(I18N_SKIP)) continue;
    const v = swap(n, 'text', n.nodeValue);
    if (v != null) n.nodeValue = v;
  }
  for (const el of root.querySelectorAll('[title], [placeholder], [aria-label]')) {
    if (el.closest(I18N_SKIP)) continue;
    for (const a of ['title', 'placeholder', 'aria-label']) {
      if (!el.hasAttribute(a)) continue;
      const v = swap(el, a, el.getAttribute(a));
      if (v != null) el.setAttribute(a, v);
    }
  }
}
